import{bV as a,aL as l,u as s,G as i}from"./chunks/framework.DxlKcdLe.js";const u=JSON.parse('{"title":"flex布局","description":"","frontmatter":{"title":"flex布局","date":"2023-03-09T16:45:23.000Z","permalink":"/pages/b9dd45/","categories":["多端","移动端"],"tags":[null]},"headers":[],"relativePath":"pages/b9dd45.md","filePath":"多端/移动端/01.flex布局.md","lastUpdated":1785138377000}'),n={name:"pages/b9dd45.md"};function t(o,e,r,d,c,p){return l(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="flex布局" tabindex="-1">flex布局 <a class="header-anchor" href="#flex布局" aria-label="Permalink to &quot;flex布局&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>flex 布局的确是很好用，而且最近在开发快应用，快应用里面只能使用 flex 布局，所以再次学一下快应用的知识</p><p>Flex 是 Flexible Box 的缩写，意为&quot;弹性布局&quot;，用来为盒状模型提供最大的灵活性。</p><p>任何一个容器都可以指定为 Flex 布局。</p></div><h2 id="一-主轴与交叉轴" tabindex="-1">一：主轴与交叉轴： <a class="header-anchor" href="#一-主轴与交叉轴" aria-label="Permalink to &quot;一：主轴与交叉轴：&quot;">​</a></h2><p>学习 flex 布局需要明白”主轴“与”交叉轴“的概念，采用 flex 布局的元素，称为”容器“ （ flex container），它的所有子元素都是容器的”项目“（flex item），容器默认存在两根轴：水平的主轴（main axis）和垂直的交叉轴（cross axis）。主轴的开始位置（与边框的交叉点）叫做 main start ，结束位置叫做 main end ；交叉轴的开始位置叫做 cross start ，结束位置叫做 cross end 。</p><p>注意，设为 Flex 布局以后，子元素的<code>float</code>、<code>clear</code>和<code>vertical-align</code>属性将失效。</p><h2 id="二-flex-容器属性" tabindex="-1">二：flex 容器属性 <a class="header-anchor" href="#二-flex-容器属性" aria-label="Permalink to &quot;二：flex 容器属性&quot;">​</a></h2><h5 id="_1-flex-direction" tabindex="-1">1.flex-direction <a class="header-anchor" href="#_1-flex-direction" aria-label="Permalink to &quot;1.flex-direction&quot;">​</a></h5><h5 id="主轴的方向" tabindex="-1">主轴的方向 <a class="header-anchor" href="#主轴的方向" aria-label="Permalink to &quot;主轴的方向&quot;">​</a></h5><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>flex-direction: row | row-reverse | column | column-reverse;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>row</code>（默认值）：主轴为水平方向，起点在左端。</li><li><code>row-reverse</code>：主轴为水平方向，起点在右端。</li><li><code>column</code>：主轴为垂直方向，起点在上沿。</li><li><code>column-reverse</code>：主轴为垂直方向，起点在下沿。</li></ul><h5 id="_2-flex-wrap" tabindex="-1">2.flex-wrap <a class="header-anchor" href="#_2-flex-wrap" aria-label="Permalink to &quot;2.flex-wrap&quot;">​</a></h5><h5 id="是否换行" tabindex="-1">是否换行 <a class="header-anchor" href="#是否换行" aria-label="Permalink to &quot;是否换行&quot;">​</a></h5><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> flex-wrap: nowrap | wrap | wrap-reverse;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>nowrap</code>（默认值）：不换行。</li><li><code>wrap</code>：换行，第一行在上方。</li><li><code>wrap-reverse</code>：换行，第一行在下方。</li></ul><h5 id="_3-justify-content" tabindex="-1">3.justify-content <a class="header-anchor" href="#_3-justify-content" aria-label="Permalink to &quot;3.justify-content&quot;">​</a></h5><h5 id="主轴的对齐方式" tabindex="-1">主轴的对齐方式 <a class="header-anchor" href="#主轴的对齐方式" aria-label="Permalink to &quot;主轴的对齐方式&quot;">​</a></h5><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  justify-content: flex-start | flex-end | center | space-around | space-between | space-between;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>flex-start</code>（默认值）：左对齐</li><li><code>flex-end</code>：右对齐</li><li><code>center</code>： 居中</li><li><code>space-around</code>：每个项目两侧的间隔相等。</li><li><code>space-between</code>：两端对齐，项目之间的间隔都相等。</li><li><code>space-evenly</code>：每个项目的间隔与项目和容器之间的间隔是相等的。</li></ul><h5 id="_4-align-items" tabindex="-1">4.align-items <a class="header-anchor" href="#_4-align-items" aria-label="Permalink to &quot;4.align-items&quot;">​</a></h5><h5 id="侧轴-交叉轴-的对齐方式" tabindex="-1">侧轴（交叉轴）的对齐方式 <a class="header-anchor" href="#侧轴-交叉轴-的对齐方式" aria-label="Permalink to &quot;侧轴（交叉轴）的对齐方式&quot;">​</a></h5><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>align-items: flex-start | flex-end | center | baseline | stretch;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>flex-start</code>：交叉轴的起点对齐。</li><li><code>flex-end</code>：交叉轴的终点对齐。</li><li><code>center</code>：交叉轴的中点对齐。</li><li><code>baseline</code>: 项目的第一行文字的基线对齐。</li><li><code>stretch</code>（默认值）: 如果项目未设置高度或设为 auto，将占满整个容器的高度。 <a href="http://www.ruanyifeng.com/blogimg/asset/2015/bg2015071011.png" target="_blank" rel="noreferrer">img</a></li></ul><h5 id="_5-align-content" tabindex="-1">5.align-content <a class="header-anchor" href="#_5-align-content" aria-label="Permalink to &quot;5.align-content&quot;">​</a></h5><p><code>align-content</code> 属性定义了多根轴线的对齐方式，前提是需要设置 flex-wrap: wrap，否则不会有效</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>align-content: flex-start | flex-end | center | space-between | space-around | stretch;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>flex-start</code>：与交叉轴的起点对齐。</li><li><code>flex-end</code>：与交叉轴的终点对齐。</li><li><code>center</code>：与交叉轴的中点对齐。</li><li><code>space-between</code>：与交叉轴两端对齐，轴线之间的间隔平均分布。</li><li><code>space-around</code>：每根轴线两侧的间隔都相等。</li><li><code>stretch</code>（默认值）：轴线占满整个交叉轴。 <img src="http://www.ruanyifeng.com/blogimg/asset/2015/bg2015071012.png" alt="img"></li></ul><h5 id="_6-flex-flow" tabindex="-1">6.flex-flow <a class="header-anchor" href="#_6-flex-flow" aria-label="Permalink to &quot;6.flex-flow&quot;">​</a></h5><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`flex-flow` 属性是 `flex-direction` 属性和 `flex-wrap` 属性的简写形式，默认值为 `row nowrap`</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`flex-flow`属性是`flex-direction`属性和`flex-wrap`属性的简写形式，默认值为`row nowrap`</span></span>\n<span class="line"><span>flex-flow: &lt;flex-direction&gt; || &lt;flex-wrap&gt;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="三-子元素属性" tabindex="-1">三：子元素属性 <a class="header-anchor" href="#三-子元素属性" aria-label="Permalink to &quot;三：子元素属性&quot;">​</a></h2><h5 id="_1-order-属性" tabindex="-1">1.order 属性 <a class="header-anchor" href="#_1-order-属性" aria-label="Permalink to &quot;1.order 属性&quot;">​</a></h5><p><code>order</code>属性定义项目的排列顺序。数值越小，排列越靠前，默认为 0。可以是负数。</p><p><img src="http://www.ruanyifeng.com/blogimg/asset/2015/bg2015071013.png" alt=""></p><h5 id="_2-flex-grow-属性" tabindex="-1">2.flex-grow 属性 <a class="header-anchor" href="#_2-flex-grow-属性" aria-label="Permalink to &quot;2.flex-grow 属性&quot;">​</a></h5><p><code>flex-grow</code>属性定义项目的放大比例，默认为<code>0</code>，即如果存在剩余空间，也不放大。</p><p><img src="http://www.ruanyifeng.com/blogimg/asset/2015/bg2015071014.png" alt="img"></p><p>flex 容器中剩余空间的多少应该分配给项目，也称为扩展规则。最终的项目的宽度为：自身宽度 + 容器剩余空间分配宽度，flex-grow 最大值是 1，超过 1 按照 1 来扩展</p><h5 id="_3-flex-shrink-属性" tabindex="-1">3.flex-shrink 属性 <a class="header-anchor" href="#_3-flex-shrink-属性" aria-label="Permalink to &quot;3.flex-shrink 属性&quot;">​</a></h5><p><code>flex-shrink</code>属性定义了项目的缩小比例，默认为 1，即如果空间不足，该项目将缩小。</p><p>flex 元素仅在默认宽度之和大于容器的时候才会发生收缩，其收缩的大小是依据 flex-shrink 的值，默认值是 1</p><h5 id="_4-flex-basis-属性" tabindex="-1">4.flex-basis 属性 <a class="header-anchor" href="#_4-flex-basis-属性" aria-label="Permalink to &quot;4.flex-basis 属性&quot;">​</a></h5><p><code>flex-basis</code>指定了子项在容器主轴方向上的初始大小，优先级高于自身的宽度 width</p><p>它可以设为跟<code>width</code>或<code>height</code>属性一样的值（比如 350px），则项目将占据固定空间。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>flex-basis: 0 | 100% | auto | &lt;length&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h5 id="_5-flex-属性" tabindex="-1">5.flex 属性 <a class="header-anchor" href="#_5-flex-属性" aria-label="Permalink to &quot;5.flex 属性&quot;">​</a></h5><p><code>flex</code>属性是<code>flex-grow</code>, <code>flex-shrink</code> 和 <code>flex-basis</code>的简写，默认值为<code>0 1 auto</code>。后两个属性可选。</p><p>该属性有两个快捷值：<code>auto</code> (<code>1 1 auto</code>) 和 none (<code>0 0 auto</code>)。</p><p>建议优先使用这个属性，而不是单独写三个分离的属性，因为浏览器会推算相关值。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>flex: none | [ &lt;&#39;flex-grow&#39;&gt;&lt;&#39;flex-shrink&#39;&gt;? || &lt;&#39;flex-basis&#39;&gt;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h5 id="_6-align-self-属性" tabindex="-1">6.align-self 属性 <a class="header-anchor" href="#_6-align-self-属性" aria-label="Permalink to &quot;6.align-self 属性&quot;">​</a></h5><p><code>align-self</code>属性允许单个项目有与其他项目不一样的对齐方式，可覆盖<code>align-items</code>属性。默认值为<code>auto</code>，表示继承父元素的<code>align-items</code>属性，如果没有父元素，则等同于<code>stretch</code>。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>align-self: auto | flex-start | flex-end | center | baseline | stretch;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',52)])])}const b=a(n,[["render",t]]);export{u as __pageData,b as default};
